create extension if not exists pgcrypto;
alter table public.lyric_songs add column if not exists distribution_style text not null default 'classic';
do $$ begin if not exists (select 1 from pg_constraint where conname='lyric_songs_distribution_style_check') then alter table public.lyric_songs add constraint lyric_songs_distribution_style_check check (distribution_style in ('classic','chat')); end if; end $$;
alter table public.lyric_songs add column if not exists current_audio_version_id uuid, add column if not exists current_timing_set_id uuid;
create table if not exists public.lyric_audio_versions (id uuid primary key default gen_random_uuid(), song_id uuid not null references public.lyric_songs(id) on delete cascade, label text not null default 'Original', audio_path text not null, duration_seconds numeric, created_by text, created_at timestamptz not null default now());
create table if not exists public.lyric_timing_sets (id uuid primary key default gen_random_uuid(), song_id uuid not null references public.lyric_songs(id) on delete cascade, audio_version_id uuid references public.lyric_audio_versions(id) on delete cascade, label text not null default 'Main Timing', created_by text, source_timing_set_id uuid, created_at timestamptz not null default now());
create table if not exists public.lyric_line_timings (timing_set_id uuid not null references public.lyric_timing_sets(id) on delete cascade, line_id uuid not null references public.lyric_song_lines(id) on delete cascade, start_ms integer, end_ms integer, updated_at timestamptz not null default now(), primary key (timing_set_id, line_id));
do $$ begin if not exists (select 1 from pg_constraint where conname='lyric_songs_current_audio_version_fk') then alter table public.lyric_songs add constraint lyric_songs_current_audio_version_fk foreign key (current_audio_version_id) references public.lyric_audio_versions(id) on delete set null; end if; if not exists (select 1 from pg_constraint where conname='lyric_songs_current_timing_set_fk') then alter table public.lyric_songs add constraint lyric_songs_current_timing_set_fk foreign key (current_timing_set_id) references public.lyric_timing_sets(id) on delete set null; end if; end $$;
create or replace function public.lyric_line_timings_set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end; $$;
drop trigger if exists trg_lyric_line_timings_updated_at on public.lyric_line_timings; create trigger trg_lyric_line_timings_updated_at before update on public.lyric_line_timings for each row execute function public.lyric_line_timings_set_updated_at();
alter table public.lyric_audio_versions enable row level security; alter table public.lyric_timing_sets enable row level security; alter table public.lyric_line_timings enable row level security;
drop policy if exists "team_read_audio_versions" on public.lyric_audio_versions; create policy "team_read_audio_versions" on public.lyric_audio_versions for select to authenticated using (public.is_team_member());
drop policy if exists "team_write_audio_versions" on public.lyric_audio_versions; create policy "team_write_audio_versions" on public.lyric_audio_versions for all to authenticated using (public.is_team_member()) with check (public.is_team_member());
drop policy if exists "team_read_timing_sets" on public.lyric_timing_sets; create policy "team_read_timing_sets" on public.lyric_timing_sets for select to authenticated using (public.is_team_member());
drop policy if exists "team_write_timing_sets" on public.lyric_timing_sets; create policy "team_write_timing_sets" on public.lyric_timing_sets for all to authenticated using (public.is_team_member()) with check (public.is_team_member());
drop policy if exists "team_read_line_timings" on public.lyric_line_timings; create policy "team_read_line_timings" on public.lyric_line_timings for select to authenticated using (public.is_team_member());
drop policy if exists "team_write_line_timings" on public.lyric_line_timings; create policy "team_write_line_timings" on public.lyric_line_timings for all to authenticated using (public.is_team_member()) with check (public.is_team_member());
grant select, insert, update, delete on public.lyric_audio_versions to authenticated; grant select, insert, update, delete on public.lyric_timing_sets to authenticated; grant select, insert, update, delete on public.lyric_line_timings to authenticated;
do $$ declare r record; v_audio_id uuid; v_timing_set_id uuid; line_has_start boolean; begin select exists (select 1 from information_schema.columns where table_schema='public' and table_name='lyric_song_lines' and column_name='start_ms') into line_has_start; for r in select * from public.lyric_songs loop if r.current_audio_version_id is null and r.audio_path is not null and r.audio_path <> '' then insert into public.lyric_audio_versions(song_id,label,audio_path,created_by) values (r.id,'Original',r.audio_path,r.created_by) returning id into v_audio_id; update public.lyric_songs set current_audio_version_id = v_audio_id where id = r.id; else v_audio_id := r.current_audio_version_id; end if; if r.current_timing_set_id is null then insert into public.lyric_timing_sets(song_id,audio_version_id,label,created_by) values (r.id,v_audio_id,'Main Timing',r.created_by) returning id into v_timing_set_id; update public.lyric_songs set current_timing_set_id = v_timing_set_id where id = r.id; if line_has_start then execute format('insert into public.lyric_line_timings(timing_set_id,line_id,start_ms,end_ms) select %L::uuid, id, start_ms, end_ms from public.lyric_song_lines where song_id=%L::uuid on conflict do nothing', v_timing_set_id, r.id); else insert into public.lyric_line_timings(timing_set_id,line_id,start_ms,end_ms) select v_timing_set_id, id, null, null from public.lyric_song_lines where song_id=r.id on conflict do nothing; end if; end if; end loop; end $$;
notify pgrst, 'reload schema';
